addEventListener('DOMContentLoaded',()=>byId('check-updates').addEventListener('click',async()=>{const button=byId('check-updates');const status=byId('update-state');const resultBox=byId('update-result');button.disabled=true;status.setAttribute('aria-busy','true');status.textContent='Checking the official GitHub release...';resultBox.innerHTML='';try{const result=await api('/wizard/api/updates/check',{method:'POST'});if(!result.available){status.textContent=`Update check unavailable: ${result.error}`;return}status.textContent=result.updateAvailable?`Version ${result.latestVersion} is available. Download it, close StreamBridge, and run the included installer.`:`You are up to date. Installed ${result.currentVersion}; latest stable ${result.latestVersion}.`;if(result.updateAvailable){const size=result.archive?`${(result.archive.size/1048576).toFixed(1)} MB`:'';const archive=result.archive?.url?`<a class="button-link" href="${safe(result.archive.url)}" target="_blank" rel="noopener noreferrer">Download Windows update${size?` (${safe(size)})`:''}</a>`:'';resultBox.innerHTML=`<article class="item"><strong>${safe(result.releaseName||`THSV StreamBridge ${result.latestVersion}`)}</strong><small>${safe(result.publishedAt?new Date(result.publishedAt).toLocaleString():'Publication date unavailable')}</small><p>${safe(String(result.releaseNotes||'').slice(0,1000))}</p><div class="button-row">${archive}<a class="button-link ghost" href="${safe(result.releaseUrl)}" target="_blank" rel="noopener noreferrer">View release notes</a></div><small>The wizard never silently replaces a live bridge. The portable installer preserves creator data and rolls back a failed activation. Compare the adjacent SHA-256 file before installing when you want manual verification.</small></article>`}}catch(error){status.textContent=error.message}finally{status.removeAttribute('aria-busy');button.disabled=false}}));
