function preferredTheme(){const saved=localStorage.getItem(themeStorageKey);if(saved==='light'||saved==='dark')return saved;return matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'}
function applyTheme(theme){const selected=theme==='light'?'light':'dark';document.documentElement.dataset.theme=selected;document.documentElement.style.colorScheme=selected;const button=byId('theme-toggle');if(!button)return;const next=selected==='dark'?'light':'dark';button.querySelector('.theme-icon').textContent=selected==='dark'?'☀':'☾';button.querySelector('.theme-label').textContent=selected==='dark'?'Light':'Dark';button.setAttribute('aria-label',`Switch to ${next} theme`);button.title=`Switch to ${next} theme`}
applyTheme(preferredTheme());
byId('theme-toggle').addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem(themeStorageKey,next)}catch{/* Theme still changes when storage is unavailable. */}applyTheme(next)});
let disclosureStates=loadDisclosureStates();
function loadDisclosureStates(){try{const value=JSON.parse(localStorage.getItem(disclosureStorageKey)||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{}}catch{return {}}}
function disclosureSlug(value){return String(value||'section').trim().toLowerCase().replace(/[^a-z0-9]+/gu,'-').replace(/^-|-$/gu,'').slice(0,100)||'section'}
function disclosureKey(details){if(details.dataset.disclosureKey)return details.dataset.disclosureKey;const addOnId=details.closest('[data-addon-id]')?.dataset.addonId;const panel=details.closest('[data-panel]')?.dataset.panel||'global';const summary=details.querySelector(':scope > summary')?.textContent||'section';const siblings=[...(details.parentElement?.children||[])].filter((element)=>element.tagName==='DETAILS'&&disclosureSlug(element.querySelector(':scope > summary')?.textContent)===disclosureSlug(summary));const occurrence=Math.max(0,siblings.indexOf(details));return `${addOnId?`addon:${addOnId}`:`panel:${panel}`}:${disclosureSlug(summary)}:${occurrence}`}
function saveDisclosureStates(){try{localStorage.setItem(disclosureStorageKey,JSON.stringify(disclosureStates))}catch{/* The wizard still works when browser storage is unavailable. */}}
function restoreDisclosureStates(root=document){const detailsList=[];if(root instanceof HTMLDetailsElement)detailsList.push(root);if(root.querySelectorAll)detailsList.push(...root.querySelectorAll('details'));for(const details of detailsList){const key=disclosureKey(details);if(typeof disclosureStates[key]==='boolean')details.open=disclosureStates[key];details.dataset.disclosureReady='true'}}
document.addEventListener('toggle',(event)=>{const details=event.target;if(!(details instanceof HTMLDetailsElement)||details.dataset.disclosureReady!=='true')return;disclosureStates[disclosureKey(details)]=details.open;saveDisclosureStates()},true);
restoreDisclosureStates();
new MutationObserver((mutations)=>{for(const mutation of mutations)for(const node of mutation.addedNodes)if(node instanceof Element)restoreDisclosureStates(node)}).observe(document.body,{childList:true,subtree:true});
document.addEventListener('click',(event)=>{const toggle=event.target.closest('[data-clamp-toggle]');if(!toggle)return;const target=toggle.previousElementSibling;const expanded=target.classList.toggle('expanded');toggle.textContent=expanded?'Show less':'Show more'});
function enhancePageHeaders(){for(const panel of document.querySelectorAll('.view[data-panel]')){if(panel.querySelector(':scope > .page-header'))continue;const first=panel.firstElementChild;if(!first)continue;const header=document.createElement('div');header.className='page-header';if(first.classList.contains('title-row')){first.classList.add('page-title-row');panel.insertBefore(header,first);header.append(first)}else if(first.matches('h2')){const copy=document.createElement('div');copy.className='page-heading-copy';panel.insertBefore(header,first);header.append(first,copy);const subtitle=header.nextElementSibling;if(subtitle?.matches('p'))copy.append(subtitle)}const heading=header.querySelector('h2');if(heading){const label=heading.textContent.trim();panel.setAttribute('aria-label',label)}}}
