const followAgeScript=[
  'if (commandSource != "twitch") return "";',
  'string viewerId = Read("userId").Trim();',
  'string broadcasterId = Read("broadcastUserId").Trim();',
  'string oauthToken = (CPH.TwitchOAuthToken ?? "").Trim();',
  'string clientId = (CPH.TwitchClientId ?? "").Trim();',
  'if (viewerId.Length == 0 || broadcasterId.Length == 0) return userName + ", Twitch did not provide the IDs needed to check follow age.";',
  'if (oauthToken.Length == 0 || clientId.Length == 0) return "Follow age is unavailable until the Twitch Broadcaster account is connected in Streamer.bot.";',
  'string url = "https://api.twitch.tv/helix/channels/followers?broadcaster_id=" + Uri.EscapeDataString(broadcasterId) + "&user_id=" + Uri.EscapeDataString(viewerId) + "&first=1";',
  'try',
  '{',
  '    var request = (System.Net.HttpWebRequest)System.Net.WebRequest.Create(url);',
  '    request.Method = "GET";',
  '    request.Timeout = 8000;',
  '    request.ReadWriteTimeout = 8000;',
  '    request.Headers["Authorization"] = "Bearer " + oauthToken;',
  '    request.Headers["Client-Id"] = clientId;',
  '    string body;',
  '    using (var response = (System.Net.HttpWebResponse)request.GetResponse())',
  '    using (var reader = new System.IO.StreamReader(response.GetResponseStream())) body = reader.ReadToEnd();',
  '    var serializer = new System.Web.Script.Serialization.JavaScriptSerializer();',
  '    var root = serializer.DeserializeObject(body) as Dictionary<string, object>;',
  '    object dataValue;',
  '    object[] data = root != null && root.TryGetValue("data", out dataValue) ? dataValue as object[] : null;',
  '    if (data == null) return "Twitch returned an unreadable follow-age response. Please try again.";',
  '    if (data.Length == 0) return userName + " is not currently following " + channelName + ".";',
  '    var follower = data[0] as Dictionary<string, object>;',
  '    object followedValue;',
  '    string followedText = follower != null && follower.TryGetValue("followed_at", out followedValue) ? Convert.ToString(followedValue) : "";',
  '    DateTimeOffset followedAt;',
  '    if (!DateTimeOffset.TryParse(followedText, System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.AssumeUniversal, out followedAt)) return "Twitch did not provide a valid follow date. Please try again.";',
  '    DateTime start = followedAt.UtcDateTime;',
  '    DateTime now = DateTime.UtcNow;',
  '    int years = now.Year - start.Year;',
  '    if (start.AddYears(years) > now) years--;',
  '    DateTime afterYears = start.AddYears(years);',
  '    int months = (now.Year - afterYears.Year) * 12 + now.Month - afterYears.Month;',
  '    if (afterYears.AddMonths(months) > now) months--;',
  '    TimeSpan remainder = now - afterYears.AddMonths(months);',
  '    var parts = new List<string>();',
  '    if (years > 0) parts.Add(years + (years == 1 ? " year" : " years"));',
  '    if (months > 0) parts.Add(months + (months == 1 ? " month" : " months"));',
  '    if (remainder.Days > 0) parts.Add(remainder.Days + (remainder.Days == 1 ? " day" : " days"));',
  '    if (parts.Count == 0 && remainder.Hours > 0) parts.Add(remainder.Hours + (remainder.Hours == 1 ? " hour" : " hours"));',
  '    if (parts.Count == 0) parts.Add(Math.Max(0, remainder.Minutes) + " minutes");',
  '    return userName + " has followed " + channelName + " for " + String.Join(", ", parts) + " (since " + followedAt.UtcDateTime.ToString("MMM d, yyyy", System.Globalization.CultureInfo.InvariantCulture) + " UTC).";',
  '}',
  'catch (System.Net.WebException error)',
  '{',
  '    var response = error.Response as System.Net.HttpWebResponse;',
  '    if (response != null && (response.StatusCode == System.Net.HttpStatusCode.Unauthorized || response.StatusCode == System.Net.HttpStatusCode.Forbidden)) return "Follow age needs Twitch follower permission. Reconnect the Twitch Broadcaster account in Streamer.bot, then try again.";',
  '    return "Twitch follow age is temporarily unavailable. Please try again later.";',
  '}',
  'catch { return "Twitch follow age is temporarily unavailable. Please try again later."; }'
].join('\n');
const lurkTrackerScript=[
  'string viewerId = Read("userId").Trim();',
  'string identity = viewerId.Length > 0 ? viewerId : (userName ?? "").Trim().ToLowerInvariant();',
  'if (identity.Length == 0) return "Lurk could not identify this viewer. Please try again from chat.";',
  'string encoded = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(identity)).TrimEnd(\'=\').Replace(\'+\', \'-\').Replace(\'/\', \'_\');',
  'string key = "thsv.command.lurk.v1." + commandSource + "." + encoded;',
  'CPH.SetGlobalVar(key, DateTime.UtcNow.Ticks, true);',
  'return "Thanks for lurking, " + userName + "! Your next chat message will automatically mark you back.";'
].join('\n');
const hugLeaderboardScript=[
  'const string countsKey = "thsv.command.hugs.counts.v1";',
  'const string namesKey = "thsv.command.hugs.names.v1";',
  'Dictionary<string, int> counts;',
  'Dictionary<string, string> names;',
  'try { counts = JsonConvert.DeserializeObject<Dictionary<string, int>>(CPH.GetGlobalVar<string>(countsKey, true) ?? "") ?? new Dictionary<string, int>(); } catch { counts = new Dictionary<string, int>(); }',
  'try { names = JsonConvert.DeserializeObject<Dictionary<string, string>>(CPH.GetGlobalVar<string>(namesKey, true) ?? "") ?? new Dictionary<string, string>(); } catch { names = new Dictionary<string, string>(); }',
  'string cleanTarget = (target ?? "").Trim().TrimStart(\'@\');',
  'if (cleanTarget.Length == 0)',
  '{',
  '    var leaders = new List<string>();',
  '    var used = new HashSet<string>(StringComparer.OrdinalIgnoreCase);',
  '    for (int rank = 0; rank < 3; rank++)',
  '    {',
  '        string bestKey = ""; int bestCount = -1;',
  '        foreach (var item in counts) if (!used.Contains(item.Key) && item.Value > bestCount) { bestKey = item.Key; bestCount = item.Value; }',
  '        if (bestKey.Length == 0) break;',
  '        used.Add(bestKey); string label; if (!names.TryGetValue(bestKey, out label)) label = bestKey;',
  '        leaders.Add(label + " (" + bestCount + ")");',
  '    }',
  '    return leaders.Count == 0 ? "No hugs have been counted yet. Use !hug followed by a viewer name." : "Hug leaders: " + String.Join(", ", leaders) + ".";',
  '}',
  'if (cleanTarget.Length > 80) cleanTarget = cleanTarget.Substring(0, 80);',
  'string targetKey = commandSource + ":" + cleanTarget.ToLowerInvariant();',
  'if (!counts.ContainsKey(targetKey) && counts.Count >= 2000) return "The hug leaderboard is full. Ask the streamer to reset it before adding a new viewer.";',
  'int total; counts.TryGetValue(targetKey, out total); total = Math.Min(Int32.MaxValue - 1, total) + 1;',
  'counts[targetKey] = total; names[targetKey] = cleanTarget + " [" + commandSource + "]";',
  'CPH.SetGlobalVar(countsKey, JsonConvert.SerializeObject(counts), true);',
  'CPH.SetGlobalVar(namesKey, JsonConvert.SerializeObject(names), true);',
  'return userName + " hugged " + cleanTarget + "! " + cleanTarget + " now has " + total + (total == 1 ? " hug." : " hugs.");'
].join('\n');
