function wizardFieldNode(form,name){const field=form.elements.namedItem(name);if(!field)return null;const element=field instanceof RadioNodeList?field.item(0):field;return element?.closest('label,fieldset')||element}
function createWizardSection(form,key,title,description,nodes,open=false){const usable=[...new Set(nodes.filter(Boolean))];if(!usable.length)return null;const details=document.createElement('details');details.className='form-section guided-form-section';details.dataset.disclosureKey=`panel:${form.closest('[data-panel]')?.dataset.panel||'global'}:${key}`;details.dataset.guidedSection=key;details.open=open;const summary=document.createElement('summary');summary.innerHTML=`<span>${safe(title)}<small>${safe(description)}</small></span>`;const body=document.createElement('div');body.className='detail-grid';body.append(...usable);details.append(summary,body);form.append(details);restoreDisclosureStates(details);return details}
function createWizardSaveRow(form,buttons,note){const row=document.createElement('div');row.className='full-row guided-save-row';row.append(...buttons.filter(Boolean));if(note){const help=document.createElement('small');help.textContent=note;row.append(help)}form.append(row);return row}
function addWizardGuide(panel,anchor,steps,note){if(!panel||!anchor||panel.querySelector(':scope > .setup-guide'))return;const guide=document.createElement('div');guide.className='setup-guide';guide.setAttribute('aria-label','Quick setup');const heading=document.createElement('strong');heading.textContent='Quick setup';const list=document.createElement('ol');for(const step of steps){const item=document.createElement('li');item.textContent=step;list.append(item)}const help=document.createElement('small');help.textContent=note;guide.append(heading,list,help);anchor.before(guide)}

