updateBlockerGuidedVisibility();updateRewardGuidedVisibility();updateChatGuidedVisibility();updateAlertGuidedVisibility();
const eventEditor=document.createElement('fieldset');eventEditor.className='full-row';eventEditor.innerHTML='<legend>Per-platform event messages</legend><label>Platform<select id="chat-event-platform"><option value="twitch">Twitch</option><option value="youtube">YouTube</option><option value="kick">Kick</option><option value="tiktok">TikTok through TikFinity</option><option value="streamlabs">Streamlabs</option><option value="kofi">Ko-fi</option></select></label><label>Wording preset<select id="chat-event-style"><option value="minimal">Minimal</option><option value="warm">Warm</option><option value="hype">Hype</option></select></label><button type="button" id="apply-chat-event-style" class="ghost">Apply to selected platform</button><p><small>Only real events for the selected platform are shown. Applying a preset replaces that platform\'s event wording but keeps its event types, tokens, character limits, aggregation, and spam gates. You can edit every message afterward.</small></p><div id="chat-event-template-editor"></div>';byId('chat-events-fieldset').after(eventEditor);
const chatPlatformEventDefinitions={
  twitch:{follow:['Follow','Twitch Follow user variables → {actor}'],subscription:['Subscription','Twitch Subscription user/tier → {actor}, {tier}'],resubscription:['Resubscription','cumulative/monthStreak/tier → {months}, {streakMonths}, {tier}'],'gift-subscription':['Single gift subscription','user/tier → {actor}, {tier}'],'gift-bomb':['Gift bomb','user/gifts/tier → {actor}, {quantity}, {tier}'],cheer:['Bits / Cheer','user/bits/message → {actor}, {quantity}, {message}'],raid:['Incoming raid','user/viewers → {actor}, {quantity}'],'reward-redemption':['Channel reward','user/rewardName/rawInput → {actor}, {rewardTitle}, {input}']},
  youtube:{subscriber:['New subscriber (free)','YouTube New Subscriber user variables → {actor}'],member:['New paid member','New Sponsor user/tier → {actor}, {tier}'],'membership-gift':['Membership gift','user/count → {actor}, {quantity}'],'member-milestone':['Member milestone','user/months → {actor}, {months}'],'super-chat':['Super Chat','user/amount/currency/message → {actor}, {amount}, {currency}, {message}'],'super-sticker':['Super Sticker','user/amount/currency → {actor}, {amount}, {currency}'],'jewels-gift':['Jewels gift','gift.name/gift.comboCount/gift.jewelsAmount → {itemName}, {quantity}, {jewelsAmount}']},
  kick:{follow:['Follow','Kick Follow user variables → {actor}'],subscription:['Subscription','user/tier → {actor}, {tier}'],resubscription:['Resubscription','user/months/tier → {actor}, {months}, {tier}'],'gift-subscription':['Single gift subscription','user/tier → {actor}, {tier}'],'mass-gift-subscription':['Mass gift subscription','user/count/tier → {actor}, {quantity}, {tier}'],'gifted-kicks':['KICKs gifted','user/amount → {actor}, {quantity}'],'reward-redemption':['Channel reward','user/rewardName/rawInput → {actor}, {rewardTitle}, {input}']},
  tiktok:{follow:['Follow','%nickname% / %username% → {actor}'],gift:['Gift','%nickname%, %giftName%, %repeatCount% → {actor}, {itemName}, {quantity}'],subscription:['Subscription','%nickname%, %subMonth% → {actor}, {months}'],likes:['Like milestone (every 100)','%totalLikeCount% / %likeCount% → {value}']}
};
chatPlatformEventDefinitions.kofi={donation:['Donation','Ko-fi from/amount/currency/message to {actor}, {amount}, {currency}, {message}']};
chatPlatformEventDefinitions.streamlabs={donation:['Donation','Stable Streamlabs event ID plus name/amount/currency/message to {actor}, {amount}, {currency}, {message}']};
const chatEventMinimalTemplates={twitch:{follow:'{actor} followed',subscription:'{actor} subscribed {tier}',resubscription:'{actor} resubscribed for {months} months {tier}','gift-subscription':'{actor} gifted a subscription {tier}','gift-bomb':'{actor} gifted {quantity} subscriptions {tier}',cheer:'{actor} cheered {quantity} bits {message}',raid:'{actor} raided with {quantity} viewers','reward-redemption':'{actor} redeemed {rewardTitle} · {input}'},youtube:{subscriber:'{actor} subscribed to the channel',member:'{actor} became a paid member {tier}','membership-gift':'{actor} gifted {quantity} memberships','member-milestone':'{actor} reached {months} months as a member','super-chat':'{actor} sent a Super Chat: {amount} {currency} {message}','super-sticker':'{actor} sent a Super Sticker: {amount} {currency}','jewels-gift':'{actor} sent {quantity} {itemName} worth {jewelsAmount} Jewels'},kick:{follow:'{actor} followed',subscription:'{actor} subscribed {tier}',resubscription:'{actor} resubscribed for {months} months {tier}','gift-subscription':'{actor} gifted a subscription {tier}','mass-gift-subscription':'{actor} gifted {quantity} subscriptions {tier}','gifted-kicks':'{actor} gifted {quantity} KICKs','reward-redemption':'{actor} redeemed {rewardTitle} · {input}'},tiktok:{follow:'{actor} followed',gift:'{actor} sent {quantity} {itemName}',subscription:'{actor} subscribed for month {months}',likes:'TikTok reached {value} likes'},streamlabs:{donation:'{actor} donated {amount} {currency} {message}'},kofi:{donation:'{actor} supported with {amount} {currency} {message}'}};
function eventStyleMessage(message,style){if(style==='warm')return `✨ ${message} — thank you!`;if(style==='hype')return `🔥 ${message} · LET'S GO!`;return message}
byId('apply-chat-event-style').addEventListener('click',()=>{if(!state.chatSettings)return;const platform=byId('chat-event-platform').value;const style=byId('chat-event-style').value;const events=state.chatSettings.chat.events.platformEvents[platform];for(const [eventId,message] of Object.entries(chatEventMinimalTemplates[platform]))events[eventId].template=eventStyleMessage(message,style);renderChatEventEditor();byId('chat-overlay-state').textContent=`${style[0].toUpperCase()+style.slice(1)} event wording applied to ${platform}. Save chat settings to stage it.`});
function renderChatEventEditor(){if(!state.chatSettings)return;const platform=byId('chat-event-platform').value;const events=state.chatSettings.chat.events.platformEvents[platform];const definitions=chatPlatformEventDefinitions[platform];const box=byId('chat-event-template-editor');box.innerHTML=`<div class="title-row"><strong>${safe(platform.toUpperCase())} events</strong><span><button type="button" class="ghost" data-toggle-platform-events="true">Enable all</button> <button type="button" class="ghost" data-toggle-platform-events="false">Disable all</button></span></div>`+Object.entries(definitions).map(([eventId,[label,source]])=>{const setting=events[eventId];return `<article class="event-template-row"><label class="check"><input type="checkbox" data-platform-event="${safe(eventId)}" ${setting.enabled?'checked':''}> ${safe(label)}</label><small>${safe(source)}</small><label>Chat activity message<input data-event-template="${safe(eventId)}" maxlength="500" value="${safe(setting.template)}"></label></article>`}).join('');box.querySelectorAll('[data-platform-event]').forEach((input)=>input.addEventListener('change',()=>{events[input.dataset.platformEvent].enabled=input.checked}));box.querySelectorAll('[data-event-template]').forEach((input)=>input.addEventListener('input',()=>{events[input.dataset.eventTemplate].template=input.value}));box.querySelectorAll('[data-toggle-platform-events]').forEach((button)=>button.addEventListener('click',()=>{const enabled=button.dataset.togglePlatformEvents==='true';for(const setting of Object.values(events))setting.enabled=enabled;renderChatEventEditor()}))}
byId('chat-event-platform').addEventListener('change',renderChatEventEditor);
document.querySelector('[data-panel="command-sync"] .transaction > p').textContent='Design the command, editable action name, trigger-variable messages, and enabled platforms. Every generated action is placed in THSV Bridge - Commands and bound to its native command. Imports remain disabled so the creator can review permissions and sources before enabling them.';
async function api(path,options={}){const response=await fetch(path,{...options,headers:{authorization:`Bearer ${state.token}`,...options.headers}});const body=await response.json();if(!response.ok)throw new Error(body.error||`Request failed (${response.status})`);return body}
function safe(value){return String(value??'').replace(/[&<>"']/g,(char)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function items(target,values,kind){byId(target).innerHTML=values.length?values.map((value)=>`<article class="item ${value.owned?'owned':''}"><strong>${safe(value.name)}</strong><small>${safe(kind==='action'?value.group:'')} ${safe(value.id)}</small><small>${value.enabled?'Enabled':'Disabled'}${kind==='command'&&!value.managed?' · Not managed by THSV StreamBridge':''}</small>${kind==='command'&&value.managed?`<button data-admin-command="${safe(value.id)}" data-admin-name="${safe(value.name)}" data-admin-operation="${value.enabled?'disable':'enable'}">${value.enabled?'Disable':'Enable'}</button>`:''}</article>`).join(''):'<p class="notice">None reported.</p>';if(kind==='command')document.querySelectorAll('[data-admin-command]').forEach((button)=>button.addEventListener('click',administerCommand));if(kind==='action'){state.liveActions=values;renderTimedActionTargets();renderTimedActions();if(state.addOns.length)renderAddOns()}}
async function administerCommand(event){const button=event.target;const commandId=button.dataset.adminCommand;const commandName=button.dataset.adminName;const operation=button.dataset.adminOperation;if(!confirm(`${operation==='enable'?'Enable':'Disable'} THSV-managed command "${commandName}" (${commandId})?`))return;const status=byId('inspection-state');button.disabled=true;status.setAttribute('aria-busy','true');status.textContent=`Requesting ${operation} for ${commandName}…`;try{const result=await api('/wizard/api/commands/administer',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({operation,commandId,approvedByCreator:true})});status.textContent=result.available?`${result.operation} requested for ${commandName}. Re-inspect to confirm.`:`Administration unavailable: ${result.error}`}catch(error){status.textContent=error.message}finally{status.removeAttribute('aria-busy');button.disabled=false}}
function renderOverview(){const value=state.overview;byId('overview-cards').innerHTML=[['Mode',value.mode],['Platforms',Object.keys(value.configuration.platforms).length],['Blocker rules',value.configuration.filters.rules.length],['Timed actions',value.configuration.timedActions.definitions.length],['Alert profiles',Object.values(value.configuration.alertSettings.alerts.profiles).reduce((total,platformProfiles)=>total+Object.keys(platformProfiles||{}).length,0)],['Version',value.version]].map(([label,data])=>`<div class="stat"><span>${safe(label)}</span><strong>${safe(data)}</strong></div>`).join('');byId('ownership').innerHTML=value.ownership.map((item)=>`<article class="item owned"><strong>${safe(item.name)}</strong><small>${safe(item.kind)} · ${safe(item.packageId)} · ${safe(item.id)}</small></article>`).join('');state.filters=structuredClone(value.configuration.filters);state.timedActions=structuredClone(value.configuration.timedActions);state.alertSettings=structuredClone(value.configuration.alertSettings);renderPlatforms();renderFilters();renderTimedActions();renderAlerts()}
const platformToggleHelp={enabled:'Master switch for this platform’s adapter. Must stay on, together with Input enabled, for anything from this platform to reach the bridge.',inputEnabled:'Chat, follows, subscriptions, gifts, raids, and reward redemptions from this platform reach the bridge. Off (or Platform enabled off) fully disables the adapter.',outputEnabled:'Reserved for future features that act back on this platform, such as reward changes. Saved with your configuration; no current feature enforces it yet.'};
function renderPlatforms(){const reports=new Map(state.overview.configuration.capabilities.map((report)=>[report.platform,report]));byId('platform-list').innerHTML=Object.entries(state.overview.configuration.platforms).map(([id,platform])=>{const report=reports.get(id);const supported=report?Object.entries(report.capabilities).filter(([,value])=>value.supported).map(([name])=>name):[];const badges=supported.length?supported.map((name)=>`<span class="cap-badge">${safe(name)}</span>`).join(''):'<span class="cap-badge">No provider declaration</span>';const limits=report?.limitations?.length?`<p class="platform-limits">Limits: ${safe(report.limitations.join(' '))}</p>`:'';return `<article class="platform-card" data-platform="${safe(id)}"><div class="platform-card-header"><div class="platform-card-name"><strong>${safe(id)}</strong><span class="platform-card-adapter">${safe(platform.adapter)}</span></div><label class="platform-toggle-main" title="${safe(platformToggleHelp.enabled)}"><input type="checkbox" data-flag="enabled" ${platform.enabled?'checked':''}> Platform enabled</label></div><div class="platform-toggle-grid"><label class="platform-toggle" title="${safe(platformToggleHelp.inputEnabled)}"><input type="checkbox" data-flag="inputEnabled" ${platform.inputEnabled?'checked':''}><span class="platform-toggle-label">Input enabled</span></label><label class="platform-toggle" title="${safe(platformToggleHelp.outputEnabled)}"><input type="checkbox" data-flag="outputEnabled" ${platform.outputEnabled?'checked':''}><span class="platform-toggle-label">Output enabled</span></label></div><div class="platform-capabilities">${badges}</div>${limits}</article>`}).join('');document.querySelectorAll('.platform-card input').forEach((input)=>input.addEventListener('change',stagePlatform))}
function renderCommandSync(result){state.trackedCommands=result.commands||[];renderCommandTree()}
function resetCommandForm(){const form=byId('design-command');form.reset();form.elements.editingIndex.value=-1;form.elements.responseMode.value='platform-message';form.elements.globalCooldown.value=0;form.elements.userCooldown.value=0;form.elements.ignoreBotAccount.checked=true;form.elements.ignoreInternal.checked=true;form.querySelector('[name="commandSource"][value="twitch"]').checked=true;updateCommandMode();updateCommandCounts()}
function hideCommandForm(){state.selectedCommandIndex=null;resetCommandForm();byId('design-command').classList.add('hidden');byId('command-editor-empty').classList.remove('hidden');renderCommandTree()}
function newCommandBatchEntry(){state.selectedCommandIndex=null;resetCommandForm();byId('command-editor-title').textContent='New command';byId('design-command').classList.remove('hidden');byId('command-editor-empty').classList.add('hidden');renderCommandTree()}
function selectCommandBatchEntry(index){const design=state.commandBatch[index];if(!design)return;state.selectedCommandIndex=index;const form=byId('design-command');form.elements.editingIndex.value=String(index);for(const field of ['name','actionName','minimumRole','note','responseMode','globalCooldown','userCooldown'])form.elements[field].value=design[field]??'';form.elements.aliases.value=design.aliases.join(', ');form.elements.messageTwitch.value=design.platformMessages.twitch||'';form.elements.messageYoutube.value=design.platformMessages.youtube||'';form.elements.messageKick.value=design.platformMessages.kick||'';form.elements.messageTiktok.value=design.platformMessages.tiktok||'';form.elements.customScript.value=design.customScript||'';form.elements.ignoreBotAccount.checked=design.ignoreBotAccount;form.elements.ignoreInternal.checked=design.ignoreInternal;for(const input of form.querySelectorAll('[name="commandSource"]'))input.checked=design.commandSources.includes(input.value);updateCommandMode();updateCommandCounts();byId('command-editor-title').textContent=`Editing ${design.name}`;form.classList.remove('hidden');byId('command-editor-empty').classList.add('hidden');renderCommandTree()}
function renderCommandTree(){const tree=byId('command-tree');const trackedGroup=`<div class="entity-list-group"><h3>Tracked commands</h3>${state.trackedCommands.length?`<ul>${state.trackedCommands.map((command)=>`<li class="entity-row"><span class="entity-item"><strong>${safe(command.name)}</strong><small>${safe(command.driftStatus)} · ${safe(command.source)}</small></span></li>`).join('')}</ul>`:'<p class="entity-list-empty">Sync to see tracked commands.</p>'}</div>`;const batchGroup=`<div class="entity-list-group"><h3>Queued in batch</h3>${state.commandBatch.length?`<ul>${state.commandBatch.map((design,index)=>`<li class="entity-row"><button type="button" class="entity-item${state.selectedCommandIndex===index?' active':''}" data-select-command="${index}"><strong>${safe(design.name)}</strong><small>${design.aliases.length?`aliases: ${safe(design.aliases.join(', '))}`:safe(design.minimumRole)}</small></button><button type="button" class="entity-remove" data-remove-batch="${index}" aria-label="Remove ${safe(design.name)} from the batch">✕</button></li>`).join('')}</ul>`:'<p class="entity-list-empty">No commands queued yet.</p>'}</div>`;tree.innerHTML=trackedGroup+batchGroup;tree.querySelectorAll('[data-select-command]').forEach((button)=>button.addEventListener('click',()=>{if(state.selectedCommandIndex===Number(button.dataset.selectCommand)){hideCommandForm();return}selectCommandBatchEntry(Number(button.dataset.selectCommand))}));tree.querySelectorAll('[data-remove-batch]').forEach((button)=>button.addEventListener('click',()=>{const index=Number(button.dataset.removeBatch);state.commandBatch.splice(index,1);if(state.selectedCommandIndex===index){state.selectedCommandIndex=null;resetCommandForm();byId('design-command').classList.add('hidden');byId('command-editor-empty').classList.remove('hidden')}else if(state.selectedCommandIndex!==null&&state.selectedCommandIndex>index){state.selectedCommandIndex-=1;const form=byId('design-command');form.elements.editingIndex.value=String(state.selectedCommandIndex)}renderCommandBatch()}))}
byId('new-command-batch-entry').addEventListener('click',newCommandBatchEntry);
byId('cancel-command-edit').addEventListener('click',hideCommandForm);
renderCommandTree();
function downloadGeneratedPackage(filename,contentBase64){const blob=new Blob([contentBase64],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=filename;link.click();URL.revokeObjectURL(url)}
function renderCommandBatch(){byId('command-batch-state').textContent=state.commandBatch.length?`${state.commandBatch.length} command(s) queued.`:'No commands queued yet.';byId('generate-batch').disabled=state.commandBatch.length===0||!byId('approve-batch').checked;renderCommandTree()}
function renderCommandGeneration(result){const box=byId('command-generation-result');if(result.collisions?.length){box.innerHTML=result.collisions.map((collision)=>`<p class="notice">Design ${safe(collision.designIndex+1)}: "${safe(collision.matchedOn)}" already matches a live ${safe(collision.kind)} named "${safe(collision.name)}" (${safe(collision.id)}). Choose a different name or alias.</p>`).join('');state.lastGeneratedCommands=[];return}if(result.package){state.lastGeneratedCommands=result.package.commands.map((command,index)=>({commandId:command.commandId,name:command.name,aliases:result.designs[index]?.aliases||[]}));box.innerHTML=`<p class="notice">Generated <code>${safe(result.package.filename)}</code> with ${safe(result.package.commands.length)} command(s).</p>${result.package.commands.map((command)=>`<article class="item"><strong>${safe(command.name)}</strong><small>command ID ${safe(command.commandId)}</small></article>`).join('')}<button id="download-generated">Download package</button> <button id="verify-generated" class="ghost">Verify import</button>`;byId('download-generated').addEventListener('click',()=>downloadGeneratedPackage(result.package.filename,result.package.contentBase64));byId('verify-generated').addEventListener('click',verifyGeneratedCommands);return}box.innerHTML=''}
async function verifyGeneratedCommands(){if(!state.lastGeneratedCommands.length)return;const status=byId('command-generation-state');status.setAttribute('aria-busy','true');status.textContent='Verifying import against a fresh inspection…';try{const result=await api('/wizard/api/commands/verify',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({commands:state.lastGeneratedCommands})});status.textContent=result.available?`Verified ${result.verifiedCommandIds.length} of ${state.lastGeneratedCommands.length} command(s). ${result.notFoundCommandIds.length} not found yet — import, bind, and enable those, then verify again.`:`Verification unavailable: ${result.error}`;if(result.commands)renderCommandSync({commands:result.commands})}catch(error){status.textContent=error.message}finally{status.removeAttribute('aria-busy')}}
function renderFilters(){const now=Date.now();const tree=byId('blocker-tree');tree.innerHTML=state.filters.rules.length?`<div class="entity-list-group"><ul>${state.filters.rules.map((rule)=>{const expired=rule.expiresAt&&Date.parse(rule.expiresAt)<=now;const active=state.selectedBlockerId===rule.id;return `<li class="entity-row"><input type="checkbox" ${rule.enabled?'checked':''} data-toggle-rule="${safe(rule.id)}" aria-label="Enable rule ${safe(rule.name)}"><button type="button" class="entity-item${active?' active':''}${rule.enabled&&!expired?'':' item-disabled'}" data-select-rule="${safe(rule.id)}"><strong>${safe(rule.name)}</strong><small>${safe(rule.scope)} · ${safe(rule.target)} · ${safe(rule.match.kind)}${rule.expiresAt?` · ${expired?'expired':`expires ${safe(new Date(rule.expiresAt).toLocaleDateString())}`}`:''}</small></button><button type="button" class="entity-remove" data-delete-rule="${safe(rule.id)}" aria-label="Delete rule ${safe(rule.name)}">✕</button></li>`}).join('')}</ul></div>`:'<p class="entity-list-empty">No blocker rules configured.</p>';tree.querySelectorAll('[data-select-rule]').forEach((button)=>button.addEventListener('click',()=>{if(state.selectedBlockerId===button.dataset.selectRule){clearBlockerForm();return}selectBlockerRule(button.dataset.selectRule)}));tree.querySelectorAll('[data-toggle-rule]').forEach((input)=>input.addEventListener('change',async()=>{const id=input.dataset.toggleRule;state.filters.rules=state.filters.rules.map((rule)=>rule.id===id?{...rule,enabled:input.checked}:rule);try{await stageFilters();if(state.selectedBlockerId===id){selectBlockerRule(id);byId('filter-state').textContent='Rule changes staged. Commit the draft to save them.'}else renderFilters()}catch(error){byId('filter-state').textContent=error.message}}));tree.querySelectorAll('[data-delete-rule]').forEach((button)=>button.addEventListener('click',async()=>{const id=button.dataset.deleteRule;const wasSelected=state.selectedBlockerId===id;state.filters.rules=state.filters.rules.filter((rule)=>rule.id!==id);try{await stageFilters();if(wasSelected)clearBlockerForm();else renderFilters()}catch(error){byId('filter-state').textContent=error.message}}))}
function toLocalDateTimeInputValue(iso){const date=new Date(iso);const pad=(value)=>String(value).padStart(2,'0');return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`}
function selectBlockerRule(id){const rule=state.filters.rules.find((item)=>item.id===id);if(!rule)return;state.selectedBlockerId=id;const form=byId('add-filter');form.elements.editingId.value=id;form.elements.name.value=rule.name;form.elements.scope.value=rule.scope;form.elements.target.value=rule.target;form.elements.kind.value=rule.match.kind;form.elements.value.value=rule.match.value;form.elements.caseSensitive.checked=rule.match.caseSensitive;form.elements.platforms.value=rule.platforms.join(', ');form.elements.moduleIds.value=rule.moduleIds.join(', ');form.elements.enabled.checked=rule.enabled;form.elements.expiresAt.value=rule.expiresAt?toLocalDateTimeInputValue(rule.expiresAt):'';updateBlockerGuidedVisibility();byId('blocker-editor-title').textContent=`Editing ${rule.name}`;form.classList.remove('hidden');byId('blocker-editor-empty').classList.add('hidden');byId('filter-state').textContent=`Editing ${rule.name}.`;renderFilters()}
function newBlockerEntry(){clearBlockerForm();updateBlockerGuidedVisibility();byId('blocker-editor-title').textContent='New rule';byId('add-filter').classList.remove('hidden');byId('blocker-editor-empty').classList.add('hidden')}
function clearBlockerForm(){state.selectedBlockerId=null;const form=byId('add-filter');form.reset();form.elements.editingId.value='';form.elements.enabled.checked=true;form.classList.add('hidden');byId('blocker-editor-empty').classList.remove('hidden');renderFilters()}
byId('new-blocker-entry').addEventListener('click',newBlockerEntry);
byId('cancel-blocker-edit').addEventListener('click',clearBlockerForm);
async function ensureDraft(){if(state.draft?.status==='draft')return state.draft;state.draft=await api('/wizard/api/transactions',{method:'POST'});renderDraft();return state.draft}
function renderDraft(message=''){byId('transaction-state').textContent=message||(state.draft?`Pending changes: ${state.draft.stagedChanges.length} section(s) staged. Nothing is saved until you commit.`:'No pending changes. Editing a setting or staging an import starts a protected draft automatically.');byId('commit').disabled=!state.draft||state.draft.stagedChanges.length===0;byId('cancel').disabled=!state.draft}
async function stagePlatform(event){try{const card=event.target.closest('[data-platform]');const values=Object.fromEntries([...card.querySelectorAll('input[data-flag]')].map((input)=>[input.dataset.flag,input.checked]));const draft=await ensureDraft();state.draft=await api(`/wizard/api/transactions/${draft.id}/stage`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({kind:'platform',platform:card.dataset.platform,...values})});renderDraft()}catch(error){renderDraft(error.message)}}
async function stageFilters(){const draft=await ensureDraft();state.draft=await api(`/wizard/api/transactions/${draft.id}/stage`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({kind:'filters',filters:state.filters})});renderDraft();byId('filter-state').textContent='Blocker rule changes staged. Commit the draft to save them.'}
async function runInspection(){const button=byId('inspect');const status=byId('inspection-state');button.disabled=true;status.setAttribute('aria-busy','true');status.textContent='Inspecting with GetActions and GetCommands…';try{const result=await api('/wizard/api/inspect',{method:'POST'});status.textContent=result.available?`Inspection completed ${new Date(result.inspectedAt).toLocaleString()}. ${result.requests.length} audited read requests.`:`Inspection unavailable: ${result.error}`;items('actions',result.actions,'action');items('commands',result.commands,'command')}catch(error){status.textContent=error.message}finally{status.removeAttribute('aria-busy');button.disabled=false}}
byId('login-form').addEventListener('submit',async(event)=>{event.preventDefault();state.token=byId('token').value.trim();byId('login-error').textContent='';try{state.overview=await api('/wizard/api/overview');renderOverview();byId('login').classList.add('hidden');byId('workspace').classList.remove('hidden');byId('mode').textContent='Authenticated · configuration mode';document.dispatchEvent(new CustomEvent('wizard:authenticated'));void runInspection()}catch(error){state.token='';byId('login-error').textContent=error.message}});
function activatePanel(panelId,{remember=true}={}){const button=document.querySelector(`[data-view="${CSS.escape(panelId)}"]`);const panel=document.querySelector(`[data-panel="${CSS.escape(panelId)}"]`);if(!button||!panel)return false;document.querySelectorAll('[data-view]').forEach((item)=>item.classList.toggle('active',item===button));document.querySelectorAll('[data-panel]').forEach((item)=>item.classList.toggle('hidden',item!==panel));if(remember)try{localStorage.setItem(panelStorageKey,panelId)}catch{/* Navigation still works without browser storage. */}panel.querySelector('h2')?.focus?.({preventScroll:true});return true}
document.querySelectorAll('[data-view]').forEach((button)=>button.addEventListener('click',()=>activatePanel(button.dataset.view)));
try{activatePanel(localStorage.getItem(panelStorageKey)||'overview',{remember:false})}catch{activatePanel('overview',{remember:false})}
byId('lock').addEventListener('click',()=>{state.token='';state.overview=null;state.draft=null;byId('token').value='';byId('workspace').classList.add('hidden');byId('login').classList.remove('hidden');byId('mode').textContent='Locked'});
byId('inspect').addEventListener('click',runInspection);
byId('add-filter').addEventListener('submit',async(event)=>{event.preventDefault();const data=new FormData(event.target);const editingId=String(data.get('editingId')||'');const id=editingId||(String(data.get('name')).trim().toLowerCase().replace(/[^a-z0-9-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,50)||`rule-${Date.now()}`);if(!editingId&&state.filters.rules.some((rule)=>rule.id===id)){byId('filter-state').textContent='Use a unique rule name.';return}const scope=String(data.get('scope'));const expiresAtLocal=String(data.get('expiresAt')||'');const rule={id,name:String(data.get('name')).trim(),enabled:data.get('enabled')==='on',scope,moduleIds:scope==='module'?String(data.get('moduleIds')).split(',').map((value)=>value.trim()).filter(Boolean):[],platforms:String(data.get('platforms')).split(',').map((value)=>value.trim().toLowerCase()).filter(Boolean),actorTypes:[],target:String(data.get('target')),match:{kind:String(data.get('kind')),value:String(data.get('value')),caseSensitive:data.get('caseSensitive')==='on'},...(expiresAtLocal?{expiresAt:new Date(expiresAtLocal).toISOString()}:{})};const previousRules=state.filters.rules;state.filters.rules=editingId?state.filters.rules.map((item)=>item.id===editingId?rule:item):[...state.filters.rules,rule];try{await stageFilters();const message=editingId?'Rule updated and staged. Commit the draft to save it.':'Rule staged. Commit the draft to save it.';clearBlockerForm();byId('filter-state').textContent=message}catch(error){state.filters.rules=previousRules;byId('filter-state').textContent=error.message}});
byId('cancel').addEventListener('click',async()=>{if(!state.draft)return;try{state.draft=await api(`/wizard/api/transactions/${state.draft.id}/cancel`,{method:'POST'});state.overview=await api('/wizard/api/overview');state.draft=null;renderOverview();renderDraft('Draft cancelled; no configuration was changed.')}catch(error){renderDraft(error.message)}});
byId('commit').addEventListener('click',async()=>{if(!state.draft)return;try{const committed=await api(`/wizard/api/transactions/${state.draft.id}/commit`,{method:'POST'});state.draft=null;state.overview=await api('/wizard/api/overview');renderOverview();renderDraft(`Committed with backup ${committed.backupPath}. Restart StreamBridge to apply the settings.`)}catch(error){renderDraft(error.message)}});
async function loadSafeConfigurationExport(){const exported=await api('/wizard/api/configuration/export');const json=JSON.stringify(exported,null,2);byId('transfer').value=json;return{exported,json}}
function configurationExportFilename(exported){return`thsv-streambridge-configuration-${String(exported.exportedAt).replace(/[:.]/gu,'-')}.json`}
function downloadConfiguration(filename,json){const blob=new Blob([`${json}\n`],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=filename;link.click();URL.revokeObjectURL(url)}
async function copyConfiguration(json){if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(json);return}byId('transfer').focus();byId('transfer').select();if(!document.execCommand('copy'))throw new Error('The browser denied clipboard access. Select and copy the JSON manually.')}
byId('export-config').addEventListener('click',async()=>{try{await loadSafeConfigurationExport();byId('transfer-state').textContent='Safe configuration preview created from the currently committed settings. Secrets are not included.'}catch(error){byId('transfer-state').textContent=error.message}});
byId('download-config').addEventListener('click',async()=>{try{const{exported,json}=await loadSafeConfigurationExport();downloadConfiguration(configurationExportFilename(exported),json);byId('transfer-state').textContent='Safe configuration JSON downloaded.'}catch(error){byId('transfer-state').textContent=error.message}});
byId('copy-config').addEventListener('click',async()=>{try{const{json}=await loadSafeConfigurationExport();await copyConfiguration(json);byId('transfer-state').textContent='Safe configuration JSON copied to the clipboard.'}catch(error){byId('transfer-state').textContent=error.message}});
byId('choose-import').addEventListener('click',()=>byId('import-file').click());
byId('import-file').addEventListener('change',async(event)=>{const file=event.target.files?.[0];if(!file)return;try{byId('transfer').value=await file.text();byId('transfer-state').textContent=`Loaded ${file.name}. Review it, then choose Stage import. Nothing has been saved.`}catch(error){byId('transfer-state').textContent=error.message}finally{event.target.value=''}});
byId('import-config').addEventListener('click',async()=>{try{const draft=await ensureDraft();state.draft=await api(`/wizard/api/transactions/${draft.id}/import`,{method:'POST',headers:{'content-type':'application/json'},body:byId('transfer').value});renderDraft();byId('transfer-state').textContent='Import staged. Review and commit to save it.'}catch(error){byId('transfer-state').textContent=error.message}});
byId('sync-commands').addEventListener('click',async()=>{const button=byId('sync-commands');const status=byId('command-sync-state');button.disabled=true;status.setAttribute('aria-busy','true');status.textContent='Syncing tracked commands against Streamer.bot…';try{const result=await api('/wizard/api/commands/sync',{method:'POST'});status.textContent=result.available?`Sync completed ${new Date(result.syncedAt).toLocaleString()}. ${result.commands.length} tracked command(s).`:`Sync unavailable: ${result.error}`;renderCommandSync(result)}catch(error){status.textContent=error.message}finally{status.removeAttribute('aria-busy');button.disabled=false}});
byId('approve-batch').addEventListener('change',renderCommandBatch);
byId('generate-batch').addEventListener('click',async()=>{const status=byId('command-generation-state');status.setAttribute('aria-busy','true');status.textContent='Checking for collisions and generating…';try{const designs=state.commandBatch.map((design)=>({...design,approvedByCreator:true}));const result=await api('/wizard/api/commands/generate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({designs})});status.textContent=result.available?(result.collisions?.length?'Collision detected — see below.':'Package generated. Review it before importing.'):`Generation unavailable: ${result.error}`;renderCommandGeneration(result);if(result.package){state.commandBatch=[];byId('approve-batch').checked=false;hideCommandForm();renderCommandBatch()}}catch(error){status.textContent=error.message}finally{status.removeAttribute('aria-busy')}});
byId('refresh-diagnostics').addEventListener('click',async()=>{byId('diagnostics').textContent=JSON.stringify(await api('/wizard/api/diagnostics'),null,2)});
renderDraft();
function renderTimedActionTargets(){const select=byId('timed-action-form')?.elements.actionId;if(!select)return;const current=select.value;const actions=state.liveActions.filter((action)=>!blockedTimedActionTargets.has(action.id));select.innerHTML='<option value="">Select an inspected action</option>'+actions.map((action)=>`<option value="${safe(action.id)}" data-name="${safe(action.name)}">${safe(action.name)} · ${safe(action.id)}</option>`).join('');select.value=current}
function timerDrift(timer){if(timer.target.provider!=='run-existing-action')return 'event-only';const live=state.liveActions.find((action)=>action.id===timer.target.actionId);if(!live)return state.liveActions.length?'missing':'not-inspected';return live.name===timer.target.actionName?'in-sync':'renamed'}
function renderTimedActions(){if(!state.timedActions)return;const tree=byId('timed-action-tree');tree.innerHTML=state.timedActions.definitions.length?`<div class="entity-list-group"><ul>${state.timedActions.definitions.map((timer)=>{const active=state.selectedTimerId===timer.id;const schedule=timer.intervalMode==='random'?`${timer.minimumMinutes}-${timer.maximumMinutes} random minutes`:`every ${timer.everyMinutes} minutes`;return `<li class="entity-row"><input type="checkbox" ${timer.enabled?'checked':''} data-toggle-timer="${safe(timer.id)}" aria-label="Enable timer ${safe(timer.name)}"><button type="button" class="entity-item${active?' active':''}${timer.enabled?'':' item-disabled'}" data-select-timer="${safe(timer.id)}"><strong>${safe(timer.name)}</strong><small>${safe(schedule)} · ${safe(timerDrift(timer))}</small></button><button type="button" class="entity-action" data-test-timer="${safe(timer.id)}" aria-label="Test ${safe(timer.name)} now">Test</button><button type="button" class="entity-remove" data-delete-timer="${safe(timer.id)}" aria-label="Delete ${safe(timer.name)}">✕</button></li>`}).join('')}</ul></div>`:'<p class="entity-list-empty">No timed actions configured.</p>';tree.querySelectorAll('[data-select-timer]').forEach((button)=>button.addEventListener('click',()=>{if(state.selectedTimerId===button.dataset.selectTimer){clearTimedActionForm();return}editTimedAction(button.dataset.selectTimer)}));tree.querySelectorAll('[data-toggle-timer]').forEach((input)=>input.addEventListener('change',async()=>{const id=input.dataset.toggleTimer;state.timedActions.definitions=state.timedActions.definitions.map((timer)=>timer.id===id?{...timer,enabled:input.checked}:timer);try{await stageTimedActions();if(state.selectedTimerId===id){editTimedAction(id);byId('timed-action-state').textContent='Timed-action changes staged. Commit and restart StreamBridge to apply them.'}else renderTimedActions()}catch(error){byId('timed-action-state').textContent=error.message}}));tree.querySelectorAll('[data-delete-timer]').forEach((button)=>button.addEventListener('click',async()=>{const timer=state.timedActions.definitions.find((item)=>item.id===button.dataset.deleteTimer);if(!confirm(`Delete timed action "${timer?.name||button.dataset.deleteTimer}" from the staged configuration?`))return;const wasSelected=state.selectedTimerId===button.dataset.deleteTimer;state.timedActions.definitions=state.timedActions.definitions.filter((item)=>item.id!==button.dataset.deleteTimer);try{await stageTimedActions();if(wasSelected)clearTimedActionForm();else renderTimedActions()}catch(error){byId('timed-action-state').textContent=error.message}}));tree.querySelectorAll('[data-test-timer]').forEach((button)=>button.addEventListener('click',async()=>{const status=byId('timed-action-state');try{const result=await api(`/wizard/api/timed-actions/${encodeURIComponent(button.dataset.testTimer)}/test`,{method:'POST'});status.textContent=`Test queued for ${result.timerId}. It is marked simulated.`}catch(error){status.textContent=error.message}}))}
function editTimedAction(id){const timer=state.timedActions.definitions.find((item)=>item.id===id);if(!timer)return;state.selectedTimerId=id;const form=byId('timed-action-form');form.elements.editingId.value=timer.id;form.elements.id.value=timer.id;form.elements.name.value=timer.name;form.elements.enabled.checked=timer.enabled;form.elements.intervalMode.value=timer.intervalMode;form.elements.everyMinutes.value=timer.everyMinutes;form.elements.minimumMinutes.value=timer.minimumMinutes??10;form.elements.maximumMinutes.value=timer.maximumMinutes??20;form.elements.firstRunAfterMinutes.value=timer.firstRunAfterMinutes??'';form.elements.missedRunPolicy.value=timer.missedRunPolicy;form.elements.selectionMode.value=timer.selection.mode;form.elements.messages.value=timer.selection.mode==='shuffle-container'?timer.selection.messages.join('\n'):'';form.elements.minimumMessages.value=timer.gates.activity.minimumMessages;form.elements.windowMinutes.value=timer.gates.activity.windowMinutes;form.elements.platforms.value=timer.gates.platforms.join(', ');form.elements.scenes.value=timer.gates.scenes.join(', ');form.elements.requireLive.checked=timer.gates.requireLive;form.elements.targetProvider.value=timer.target.provider;form.elements.actionId.value=timer.target.provider==='run-existing-action'?timer.target.actionId:'';
if(timer.target.provider==='run-existing-action'&&form.elements.actionId.value!==timer.target.actionId){const savedOption=document.createElement('option');savedOption.value=timer.target.actionId;savedOption.textContent=`${timer.target.actionName} (saved) — Inspect Streamer.bot to verify`;form.elements.actionId.append(savedOption);form.elements.actionId.value=timer.target.actionId}const deliveryPlatforms=timer.target.provider==='run-existing-action'?(timer.target.deliveryPlatforms||[]):[];form.querySelectorAll('[name="deliveryPlatform"]').forEach((input)=>{input.checked=deliveryPlatforms.includes(input.value)});byId('timed-action-editor-title').textContent=`Editing ${timer.name}`;form.classList.remove('hidden');byId('timed-action-editor-empty').classList.add('hidden');byId('timed-action-state').textContent=`Editing ${timer.name}.`;renderTimedActions()}
