function renderChatOverlayPreview(){
  const form=byId('chat-overlay-form');if(!form)return;
  const card=byId('chat-preview-card');const list=byId('chat-preview-list');
  card.dataset.layout=form.elements.layout.value;
  const fontFamilies={system:'"Segoe UI Variable Text","Segoe UI",Arial,sans-serif',rounded:'"Arial Rounded MT Bold","Segoe UI",Arial,sans-serif',monospace:'Consolas,"Cascadia Mono",monospace'};
  card.style.fontFamily=fontFamilies[form.elements.fontFamily.value]||fontFamilies.system;
  card.style.fontSize=`${form.elements.fontSizePx.value||18}px`;
  card.style.background=form.elements.backgroundMode.value==='solid'?rgbaHex(form.elements.backgroundColor.value,form.elements.backgroundOpacity.value):'transparent';
  const messageColorMode=form.elements.messageColorMode.value;
  const messageOpacity=form.elements.messageBackgroundOpacity.value;
  const singleMessageBg=rgbaHex(form.elements.messageBackgroundColor.value,messageOpacity);
  const platformColors={twitch:form.elements.platformColorTwitch.value,youtube:form.elements.platformColorYoutube.value,kick:form.elements.platformColorKick.value,tiktok:form.elements.platformColorTiktok.value,streamlabs:form.elements.platformColorStreamlabs.value,kofi:form.elements.platformColorKofi.value};
  const showPlatformLabels=form.elements.showPlatformLabels.checked;
  const showProfilePictures=form.elements.showProfilePictures.checked;
  const showBadges=form.elements.showBadges.checked;
  const textColor=form.elements.textColor.value;
  const messageBackground=(platform)=>messageColorMode==='transparent'?'transparent':messageColorMode==='platform'?rgbaHex(platformColors[platform]||'#171120',messageOpacity):singleMessageBg;
  const rows=previewChatMessages.map((entry)=>{
    const avatar=showProfilePictures?`<span class="preview-chat-avatar" style="background:${previewPlatformAccents[entry.platform]}33;color:${previewPlatformAccents[entry.platform]}">${safe(entry.name.charAt(0))}</span>`:'';
    const platformLabel=showPlatformLabels?`<span class="preview-chat-platform">${safe(previewPlatformLabels[entry.platform])}</span>`:'';
    const role=showBadges&&entry.role?`<span class="preview-chat-role">${safe(entry.role)}</span>`:'';
    return `<li class="preview-chat-message" style="background:${messageBackground(entry.platform)};border-left-color:${previewPlatformAccents[entry.platform]}"><div class="preview-chat-identity">${avatar}${platformLabel}<span class="preview-chat-name">${safe(entry.name)}</span>${role}</div><p class="preview-chat-body" style="color:${safe(textColor)}">${safe(entry.message)}</p></li>`;
  });
  if(form.elements.showEvents.checked){
    const platformLabel=showPlatformLabels?'<span class="preview-chat-platform">TWITCH</span>':'';
    rows.push(`<li class="preview-chat-message" style="background:${messageBackground('twitch')};border-left-color:${previewPlatformAccents.twitch}"><div class="preview-chat-identity">${platformLabel}<span class="preview-chat-name" style="color:#8ee9c9">New follower: ExampleFollower 🎉</span></div></li>`);
  }
  list.innerHTML=rows.join('');
}
