byId('reward-admin-form').addEventListener('submit',async(event)=>{event.preventDefault();const form=event.target;if(!form.checkValidity()){form.reportValidity();return}const data=new FormData(form);const platform=String(data.get('platform'));const operation=String(data.get('operation'));const rewardId=String(data.get('rewardId')||'').trim();const redemptionId=String(data.get('redemptionId')||'').trim();const status=byId('reward-admin-state');if((operation==='fulfill'||operation==='cancel')&&!redemptionId){status.textContent='Fulfill and cancel require the exact redemption ID.';return}if(!confirm(`Run Twitch reward operation "${operation}" on reward ${rewardId}? This changes the live reward in Streamer.bot.`))return;status.setAttribute('aria-busy','true');status.textContent='Requesting documented Twitch reward operation…';try{const result=await api('/wizard/api/rewards/administer',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({platform,operation,rewardId,...(redemptionId?{redemptionId}:{}),approvedByCreator:true})});status.textContent=result.available?`${result.operation} requested for reward ${result.rewardId}. Check Streamer.bot Action History to confirm completion.`:`Reward operation unavailable: ${result.error}`;if(result.available){rememberRecentReward(platform,rewardId);form.reset();updateRewardGuidedVisibility()}}catch(error){status.textContent=error.message}finally{status.removeAttribute('aria-busy')}});
const RECENT_REWARDS_KEY='thsv-recent-rewards';
function loadRecentRewards(){try{return JSON.parse(localStorage.getItem(RECENT_REWARDS_KEY)||'[]')}catch{return[]}}
function saveRecentRewards(list){try{localStorage.setItem(RECENT_REWARDS_KEY,JSON.stringify(list.slice(0,8)))}catch{/* localStorage may be unavailable; the quick-select list is a convenience, not required. */}}
function renderRecentRewards(){const list=loadRecentRewards();const host=byId('recent-rewards');if(!list.length){host.innerHTML='';return}host.innerHTML=`<strong class="preview-label">Recent reward IDs</strong><div class="recent-rewards-chips">${list.map((entry,index)=>`<button type="button" data-recent-reward="${index}">${safe(platformLabels[entry.platform]||entry.platform)} · ${safe(entry.rewardId.slice(0,8))}…</button>`).join('')}</div>`;host.querySelectorAll('[data-recent-reward]').forEach((button)=>button.addEventListener('click',()=>{const entry=list[Number(button.dataset.recentReward)];if(!entry)return;const form=byId('reward-admin-form');form.elements.platform.value=entry.platform;form.elements.rewardId.value=entry.rewardId;form.elements.rewardId.focus()}))}
function rememberRecentReward(platform,rewardId){const list=loadRecentRewards().filter((entry)=>!(entry.platform===platform&&entry.rewardId===rewardId));list.unshift({platform,rewardId});saveRecentRewards(list);renderRecentRewards()}
renderRecentRewards();
